class Solution {
    public int flipgame(int[] fronts,int[] backs){
        Set<Integer> forbidden=new HashSet<>();
        for(int i=0;i<fronts.length;i++)if(fronts[i]==backs[i])forbidden.add(fronts[i]);
        int answer=Integer.MAX_VALUE;
        for(int value:fronts)if(!forbidden.contains(value))answer=Math.min(answer,value);
        for(int value:backs)if(!forbidden.contains(value))answer=Math.min(answer,value);
        return answer==Integer.MAX_VALUE?0:answer;
    }
}

code.kotlin:
class Solution {
    fun flipgame(fronts:IntArray,backs:IntArray):Int{
        val forbidden=mutableSetOf<Int>();
        for(i in fronts.indices)if(fronts[i]==backs[i])forbidden.add(fronts[i]);
        var answer=Int.MAX_VALUE;
        for(value in fronts)if(value !in forbidden)answer=minOf(answer,value);
        for(value in backs)if(value !in forbidden)answer=minOf(answer,value);
        return if(answer==Int.MAX_VALUE)0 else answer
    }
}

